function field(label,name,value='',type='text',opts={}) {
  const isUrl=type==='url',inputType=isUrl?'text':type;
  const attrs=`name="${name}" ${opts.required?'required':''} ${opts.min!=null?`min="${opts.min}"`:''} ${opts.max!=null?`max="${opts.max}"`:''} ${opts.step!=null?`step="${opts.step}"`:''} ${opts.minlength!=null?`minlength="${opts.minlength}"`:''} ${opts.maxlength!=null?`maxlength="${opts.maxlength}"`:''} ${isUrl?'inputmode="url" data-url-input="1"':''}`;
  if (type==='textarea') return `<label class="${opts.wide?'wide':''}">${label}<textarea ${attrs} rows="${opts.rows||4}">${esc(value)}</textarea></label>`;
  if (type==='select') return `<label class="${opts.wide?'wide':''}">${label}<select ${attrs}>${opts.options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(typeof value==='boolean'?Number(value):value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
  return `<label class="${opts.wide?'wide':''}">${label}<input ${attrs} type="${inputType}" value="${esc(value)}" ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:isUrl?'placeholder="https://example.com/image.webp or /uploads/image.webp"':''}>${isUrl?'<small class="field-hint">Use an HTTP(S) address or a local path beginning with /.</small>':''}</label>`;
}
function validWebUrl(value) { if(!value)return true;if(value.startsWith('/')&&!value.startsWith('//')&&!value.includes('\\'))return true;try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password;}catch{return false;} }
function validateUrlInput(input) { const valid=validWebUrl(input.value.trim());input.setCustomValidity(valid?'':'Use an HTTP(S) address or a local path beginning with /.');input.toggleAttribute('aria-invalid',!valid);return valid; }
